@page "/"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Shipment Tracker</PageTitle>

<h1>Shipment Tracker</h1>
<p>Track your shipments in real time. Enter a tracking number below to get started.</p>

<div class="card p-4 mb-4">
    <h3>Track a Shipment</h3>
    <div class="input-group">
        <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001-ABC)"
               @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
        <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
            Track
        </button>
    </div>
    @if (searchPerformed && shipment is null)
    {
        <div class="alert alert-warning mt-3">No shipment found with that tracking number.</div>
    }
</div>

@if (shipment is not null)
{
    <div class="card p-4">
        <h4>Shipment Details</h4>
        <table class="table">
            <tr><th>Tracking Number</th><td>@shipment.TrackingNumber</td></tr>
            <tr><th>Description</th><td>@shipment.Description</td></tr>
            <tr><th>Origin</th><td>@shipment.Origin</td></tr>
            <tr><th>Destination</th><td>@shipment.Destination</td></tr>
            <tr><th>Status</th><td><span class="badge bg-info">@shipment.Status</span></td></tr>
            <tr><th>Shipped Date</th><td>@shipment.ShippedDate.ToShortDateString()</td></tr>
            <tr><th>Estimated Delivery</th><td>@shipment.EstimatedDelivery.ToShortDateString()</td></tr>
            @if (shipment.ActualDelivery.HasValue)
            {
                <tr><th>Actual Delivery</th><td>@shipment.ActualDelivery.Value.ToShortDateString()</td></tr>
            }
        </table>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private Shipment? shipment;
    private bool searchPerformed;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searchPerformed = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }
}

