    <select class="form-select w-auto d-inline-block" @bind="selectedFilter">
        <option value="">All</option>
        @foreach (var status in Enum.GetValues<ShipmentStatus>())
        {
            <option value="@status">@status</option>
        }
    </select>
    <button class="btn btn-secondary ms-2" @onclick="LoadShipments">Refresh</button>
</div>

@if (loading)
{
    <p>Loading shipments...</p>
}
else if (filteredShipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Description</th>
                <th>Destination</th>
                <th>Status</th>
                <th>ETA</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in filteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Description</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.EstimatedDelivery.ToShortDateString()</td>
                    <td>
                        <select class="form-select form-select-sm d-inline-block w-auto"
                                @onchange="(e) => UpdateStatus(shipment.Id, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(status == shipment.Status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment> allShipments = new();
    private string selectedFilter = string.Empty;
    private bool loading = true;

    private List<Shipment> filteredShipments =>
        string.IsNullOrEmpty(selectedFilter)
            ? allShipments
            : allShipments.Where(s => s.Status.ToString() == selectedFilter).ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        allShipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            await LoadShipments();
        }
    }

    private string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "primary",
        ShipmentStatus.InTransit => "info",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>My Shipments</PageTitle>

<h1>My Shipments</h1>

<div class="mb-3">
    <button class="btn btn-secondary" @onclick="LoadShipments">Refresh</button>
</div>

@if (loading)
{
    <p>Loading your shipments...</p>
}
else if (shipments.Count == 0)
{
    <p>You have no shipments.</p>
}
else
{
    <div class="row">
        @foreach (var shipment in shipments)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@shipment.TrackingNumber</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@shipment.Description</h6>
                        <p class="card-text">
                            <strong>Destination:</strong> @shipment.Destination<br />
                            <strong>Status:</strong> <span class="badge bg-info">@shipment.Status</span><br />
                            <strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToShortDateString()
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <br /><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToShortDateString()
                            }
                        </p>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<Shipment> shipments = new();
    private bool loading = true;

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.Identity?.Name ?? string.Empty;
        shipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
        loading = false;
    }
}

@page "/track/{TrackingNumber?}"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Shipment</h1>

<div class="mb-4">
    <div class="input-group">
        <input type="text" class="form-control" placeholder="Enter tracking number"
               @bind="searchNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
        <button class="btn btn-primary" @onclick="Search" disabled="@string.IsNullOrWhiteSpace(searchNumber)">
            Search
        </button>
    </div>
</div>

@if (loading)
{
    <p>Searching...</p>
}
else if (searched && shipment is null)
{
    <div class="alert alert-warning">No shipment found with tracking number "@displayedNumber".</div>
}
else if (shipment is not null)
{
    <div class="card p-4">
        <h4>@shipment.TrackingNumber</h4>
        <p class="text-muted">@shipment.Description</p>
        <table class="table">
            <tr><th>Origin</th><td>@shipment.Origin</td></tr>
            <tr><th>Destination</th><td>@shipment.Destination</td></tr>
            <tr><th>Status</th><td><span class="badge bg-info">@shipment.Status</span></td></tr>
            <tr><th>Shipped</th><td>@shipment.ShippedDate.ToShortDateString()</td></tr>
            <tr><th>Estimated Delivery</th><td>@shipment.EstimatedDelivery.ToShortDateString()</td></tr>
            @if (shipment.ActualDelivery.HasValue)
            {
                <tr><th>Actual Delivery</th><td>@shipment.ActualDelivery.Value.ToShortDateString()</td></tr>
            }
        </table>
    </div>
}

@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private string searchNumber = string.Empty;
    private string displayedNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;
    private bool loading;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            searchNumber = TrackingNumber;
            await Search();
        }
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(searchNumber)) return;
        loading = true;
        searched = true;
        displayedNumber = searchNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(displayedNumber);
        loading = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await Search();
        }
    }
}

